using FiveSmartFarmCreators.Ichu.Platform.OperationsMonitoring.Domain.Model.ValueObjects;

namespace FiveSmartFarmCreators.Ichu.Platform.OperationsMonitoring.Domain.Model.Aggregates;

/// <summary>
///     Aggregate root representing a field event observed by an operator or a clinical intervention applied by a
///     veterinarian. Its identifier is the operation identifier generated by the client, so offline retries never
///     create a second record.
/// </summary>
public sealed class LivestockOperation
{
    /// <summary>Maximum number of characters of an observation.</summary>
    public const int MaximumObservationLength = 500;

    /// <summary>Maximum number of characters of a product name.</summary>
    public const int MaximumProductLength = 120;

    /// <summary>Maximum number of characters of a dose.</summary>
    public const int MaximumDoseLength = 60;

    private LivestockOperation()
    {
    }

    /// <summary>
    ///     Initializes a new instance of the <see cref="LivestockOperation"/> class.
    /// </summary>
    /// <param name="operationId">The identifier generated by the client for the operation.</param>
    /// <param name="ranchId">The ranch that owns the animal.</param>
    /// <param name="cattleId">The animal the operation was applied to.</param>
    /// <param name="type">The kind of operation.</param>
    /// <param name="occurredAt">The instant the operation happened.</param>
    /// <param name="authorId">The account that registered the operation.</param>
    /// <param name="observation">A free-text observation, if any.</param>
    /// <param name="product">The administered product, only for clinical interventions.</param>
    /// <param name="dose">The administered dose, only for clinical interventions.</param>
    /// <param name="receivedAt">The instant the cloud received the operation.</param>
    /// <exception cref="ArgumentException">Thrown when an identifier is empty or a text is invalid.</exception>
    public LivestockOperation(
        Guid operationId,
        Guid ranchId,
        Guid cattleId,
        OperationType type,
        DateTimeOffset occurredAt,
        Guid authorId,
        string? observation,
        string? product,
        string? dose,
        DateTimeOffset receivedAt)
    {
        if (operationId == Guid.Empty || ranchId == Guid.Empty || cattleId == Guid.Empty || authorId == Guid.Empty)
        {
            throw new ArgumentException("Operation, ranch, animal and author identifiers are required.");
        }

        var normalizedProduct = Normalize(product, MaximumProductLength, "product");
        var normalizedDose = Normalize(dose, MaximumDoseLength, "dose");
        if (!IsClinical(type) && (normalizedProduct is not null || normalizedDose is not null))
        {
            throw new ArgumentException("Only clinical interventions record an administered product or dose.");
        }

        Id = operationId;
        RanchId = ranchId;
        CattleId = cattleId;
        Type = type;
        OccurredAt = occurredAt.ToUniversalTime();
        AuthorId = authorId;
        Observation = Normalize(observation, MaximumObservationLength, "observation");
        Product = normalizedProduct;
        Dose = normalizedDose;
        ReceivedAt = receivedAt.ToUniversalTime();
    }

    /// <summary>Gets the identifier generated by the client for the operation.</summary>
    public Guid Id { get; private set; }

    /// <summary>Gets the ranch that owns the animal.</summary>
    public Guid RanchId { get; private set; }

    /// <summary>Gets the animal the operation was applied to.</summary>
    public Guid CattleId { get; private set; }

    /// <summary>Gets the kind of operation.</summary>
    public OperationType Type { get; private set; }

    /// <summary>Gets the instant the operation happened.</summary>
    public DateTimeOffset OccurredAt { get; private set; }

    /// <summary>Gets the instant the cloud received the operation.</summary>
    public DateTimeOffset ReceivedAt { get; private set; }

    /// <summary>Gets the account that registered the operation.</summary>
    public Guid AuthorId { get; private set; }

    /// <summary>Gets the free-text observation, if any.</summary>
    public string? Observation { get; private set; }

    /// <summary>Gets the administered product, if any.</summary>
    public string? Product { get; private set; }

    /// <summary>Gets the administered dose, if any.</summary>
    public string? Dose { get; private set; }

    /// <summary>
    ///     Determines whether an operation type is a clinical intervention applied by a veterinarian.
    /// </summary>
    /// <param name="type">The operation type.</param>
    /// <returns><see langword="true"/> for vaccinations, treatments and inseminations.</returns>
    public static bool IsClinical(OperationType type) =>
        type is OperationType.Vaccination or OperationType.Treatment or OperationType.Insemination;

    /// <summary>
    ///     Determines whether another operation carries the same content, as a retry of the same operation does.
    /// </summary>
    /// <param name="other">The operation to compare with.</param>
    /// <returns><see langword="true"/> when both operations have the same content.</returns>
    public bool HasSameContentAs(LivestockOperation other) =>
        Id == other.Id &&
        CattleId == other.CattleId &&
        Type == other.Type &&
        OccurredAt == other.OccurredAt &&
        AuthorId == other.AuthorId &&
        Observation == other.Observation &&
        Product == other.Product &&
        Dose == other.Dose;

    private static string? Normalize(string? value, int maximumLength, string field)
    {
        if (string.IsNullOrWhiteSpace(value))
        {
            return null;
        }

        var normalized = value.Trim();
        if (normalized.Length > maximumLength)
        {
            throw new ArgumentException($"The {field} cannot exceed {maximumLength} characters.");
        }

        return normalized;
    }
}
